import sys


def main():
    data = sys.stdin.buffer.read().split(b"\n")
    sums = {}
    get = sums.get
    for line in data[1:]:
        if not line:
            continue
        parts = line.split(b",")
        if len(parts) < 3:
            continue
        cat = parts[1]
        val = float(parts[2])
        sums[cat] = get(cat, 0.0) + val
    out = []
    for cat in sorted(sums):
        out.append(cat.decode() + "," + ("%.2f" % sums[cat]))
    if out:
        sys.stdout.write("\n".join(out) + "\n")


main()

import sys


def main():
    data = sys.stdin.buffer.read().split(b"\n")
    sums = {}
    for line in data[1:]:
        p = line.split(b",")
        if len(p) < 3:
            continue
        c = p[1]
        sums[c] = sums.get(c, 0.0) + float(p[2])
    out = [c.decode() + "," + ("%.2f" % sums[c]) for c in sorted(sums)]
    if out:
        sys.stdout.write("\n".join(out) + "\n")


main()
